      "id": 717944234189,
      "title": "První revize OP TAK (2021-2027) byla schválena Evropskou komisí",
      "code": "",
      "type": "Dotace",
      "type_code": "grant",
      "status": "Neznámé",
      "status_code": "unknown",
      "opening_date": "",
